import { Row, Col } from 'antd'
import { getFormItems } from '../formItem'
import { size } from 'lodash'
import { capitalizeFirstLetter } from '../../../../../../helpers/utility'
import styled from 'styled-components'

const StyleContainer = styled.div`
  padding-top:10px;
  padding-bottom:10px;
  .padding__left {
    padding-left:20px;
  }
`
export function ObjectTypeField ({ formName, parentKey, fields, form }) {
  const parentKeyLocal = formName

  return (
    <StyleContainer>
      <Row type='flex'>
        <Col span={24}>
          <h4><b>{parentKey}(object)</b></h4>
        </Col>
        {
          size(fields) > 0 &&
          Object.keys(fields).map((item, index) => {
            const data = getFormItems.call(this, {
              form,
              formName: `${parentKeyLocal}.${item}`,
              type: fields[item],
              label: capitalizeFirstLetter(item),
              initialValue: '',
              required: true,
              parentKey: capitalizeFirstLetter(item)
            })
            return (
              <Col className='padding__left' key={index} span={24}>
                {data}
              </Col>
            )
          })
        }
      </Row>
    </StyleContainer>
  )
}
