import { Row, Col, Input, Icon } from 'antd'
import React, { useState } from 'react'
import { ArrayOfString as StyleContainer } from './commanStyles.style'

export function ArrayOfString ({ form, formName, parentKey, getFieldDecorator }) {
  const [fields, setFields] = useState([{ id: 0, showAdd: true, showDelete: false }])

  const addItem = () => {
    const lastItemId = fields[fields.length - 1].id
    const updatedItem = [...fields, {
      ...fields[0],
      id: lastItemId + 1
    }].map(item => {
      return {
        ...item,
        showAdd: true,
        showDelete: true
      }
    })
    setFields(updatedItem)
  }

  const remove = (id) => {
    let updatedItems = fields.filter(item => item.id !== id)
    if (updatedItems.length === 1) {
      updatedItems = updatedItems.map(item => {
        return {
          ...item,
          showDelete: false
        }
      })
    }
    setFields(updatedItems)
  }
  return (
    <StyleContainer>
      <Row type='flex'>
        <Col span={24}>
          {
              parentKey &&
                <div className='array_of_string__head'>
                  <h4><b>{parentKey}</b></h4>
                </div>
          }
        </Col>
        <Col span={24}>
          <Row type='flex' justify='space-between' align='middle' gutter={30}>
            {
              fields.map((item, index) => {
                return (
                  <React.Fragment key={index}>
                    <Col className='input__items' span={2}>
                      <span><b>Item {index} </b></span>
                    </Col>
                    <Col span={20}>
                      {
                        getFieldDecorator(`${formName}[${index}]`)(<Input />)
                      }
                    </Col>
                    <Col span={2}>
                      <Row type='flex' gutter={20}>
                        {
                          item.showAdd &&
                            <Col>
                              <Icon
                                className='dynamic-add-button button-size'
                                type='plus-circle'
                                theme='filled'
                                onClick={addItem}
                              />
                            </Col>
                        }
                        {
                          item.showDelete &&
                            <Col>
                              <Icon
                                className='dynamic-delete-button button-size'
                                type='minus-circle'
                                theme='filled'
                                onClick={() => remove(item.id)}
                              />
                            </Col>
                        }
                      </Row>
                    </Col>
                  </React.Fragment>
                )
              })
            }
          </Row>
        </Col>
      </Row>
    </StyleContainer>
  )
}
