/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect } from 'react'
import { Row, Col, Card, Select, notification, Spin } from 'antd'
import { useResetState, useGetPackageList, useProductPackageAttributes } from '../hooks/useTestCreatePolicy'
import { get } from 'lodash'
import { CardContainer } from './cardComponent.style'
const { Option } = Select

export default function TopComponent ({ product, partner, packageDataFunction }) {
  const [loading, setLoading] = useState(false)
  const [packages, setPackages] = useState([])
  const [{ getPackagesData, getPackagesStatus }, getPackagesList] = useGetPackageList()
  const [{ getProductPackageAttributesStatus }, request] = useProductPackageAttributes()
  const [resetTestCreatePolicyState] = useResetState()

  useEffect(() => {
    if (getProductPackageAttributesStatus === 'success') {
      setLoading(false)
    }
    if (getProductPackageAttributesStatus !== 'success' && getProductPackageAttributesStatus !== undefined) {
      setLoading(false)
    }
    if (getPackagesStatus === 'success') {
      setPackages(getPackagesData)
      resetTestCreatePolicyState(['getPackagesStatus'])
    }
    if (getPackagesStatus !== 'success' && getPackagesStatus !== undefined) {
      notification.error({
        message: get(getPackagesData, 'message', '')
      })
      resetTestCreatePolicyState(['getPackagesStatus'])
    }
  }, [getPackagesStatus, getProductPackageAttributesStatus])

  useEffect(() => {
    if (partner && product) {
      getPackagesList({
        query: {
          product_code: product,
          partner_code: partner
        }
      })
    }
  }, [product, partner])

  const changePackages = (e) => {
    packageDataFunction(e)
    setLoading(true)
    request({
      query: {
        product_code: product,
        package_code: e
      }
    })
  }

  return (
    <CardContainer>
      <Spin spinning={loading}>
        <Card>
          <Row type='flex'>
            <Col span={8}>
              <span><b>Product</b></span>
            </Col>
            <Col span={8}>
              <span>{product}</span>
            </Col>
          </Row>
          <Row className='padding10' type='flex'>
            <Col span={8}>
              <span><b>Partner</b></span>
            </Col>
            <Col span={8}>
              <span>{partner}</span>
            </Col>
          </Row>
          <Row className='padding10' type='flex'>
            <Col span={8}>
              <span><b>Package</b></span>
            </Col>
            <Col span={8}>
              <Select
                showSearch
                filterOption={
                  (input, option) =>
                    option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                }
                onChange={changePackages}
                className='select_packages'
              >
                {
                  packages.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)
                }
              </Select>
            </Col>
          </Row>
        </Card>
      </Spin>
    </CardContainer>
  )
}
