import { useState, useEffect } from 'react'
import { Card, Collapse, notification, Row, Col, Button } from 'antd'
import styled from 'styled-components'
import { get, size } from 'lodash'
import PolicyAttributes from './policyAttributes'
import EndorsementAttributes from './endorsementAttributes'
import { useResetState, useProductPackageAttributes } from '../hooks/useTestCreatePolicy'
import { useHistory } from 'react-router'
// import { useLoaderContextValue } from '../../../../../globalContextProvider/LoaderContext'

const { Panel } = Collapse
const CardContainer = styled.div`
  margin-top: 40px;
  margin-bottom: 40px;
  .column__button_row {
    margin-bottom:20px;
  }
  .button_policy {
    float:right;
    background: cyan;
    color: #000;
  }
`

export default function AccordianComponent ({ partner, product, packageKey }) {
  const [accordianState, setAccordianState] = useState(['1'])
  const [policyAttribute, setPolicyAttribute] = useState({})
  const [refData, setRef] = useState('')
  const [endorsementAttribute, setEndorsementAttribute] = useState({})
  const [{ getProductPackageAttributesData, getProductPackageAttributesStatus }] = useProductPackageAttributes()
  const [resetTestCreatePolicyState] = useResetState()
  const history = useHistory()

  // const [{ GET_PRODUCT_PACKAGE_ATTRIBUTES }] = useLoaderContextValue()

  useEffect(() => {
    if (getProductPackageAttributesStatus === 'success') {
      const policyAttributes = get(getProductPackageAttributesData, 'request', {})
      const endorsementAttributes = get(getProductPackageAttributesData, 'endorsement', {})
      setPolicyAttribute(policyAttributes)
      setEndorsementAttribute(endorsementAttributes)
      resetTestCreatePolicyState(['getProductPackageAttributesStatus'])
    }
    if (getProductPackageAttributesStatus !== 'success' && getProductPackageAttributesStatus !== undefined) {
      notification.error({
        message: get(getProductPackageAttributesData, 'message', '')
      })
      resetTestCreatePolicyState(['getProductPackageAttributesStatus'])
    }
  }, [getProductPackageAttributesStatus, getProductPackageAttributesData, resetTestCreatePolicyState])

  const setPolicyAttributesRefNumber = (ref) => {
    setRef(ref)
    if (size(endorsementAttribute) > 0) {
      setAccordianState(['1', '2'])
    }
  }

  const goToPolicyDetails = () => {
    history.push({
      pathname: `/policy/${refData}`
    })
  }
  return (
    <CardContainer>
      {
        size(policyAttribute) > 0 &&
          <Card>
            <Row type='flex' justify='center'>
              {
                refData &&
                  <Col className='column__button_row' span={22}>
                    <Button className='button_policy' onClick={goToPolicyDetails}>Go to Policy Detail</Button>
                  </Col>
              }
              <Col span={22}>
                <Collapse activeKey={accordianState}>
                  <Panel header='Policy' key='1'>
                    <PolicyAttributes
                      data={policyAttribute}
                      partner={partner}
                      product={product}
                      packageKey={packageKey}
                      refPicker={setPolicyAttributesRefNumber}
                    />
                  </Panel>
                  {
                    size(endorsementAttribute) > 0 &&
                      <Panel header='Endorsement' key='2'>
                        <EndorsementAttributes
                          data={endorsementAttribute}
                          partner={partner}
                          product={product}
                          refData={refData}
                        />
                      </Panel>
                  }
                </Collapse>
              </Col>
            </Row>

          </Card>
      }
    </CardContainer>
  )
}
