import { mapArrayElementsKeysToObjectKeys } from '../../../../helpers/utility'
import actions from './actions'

const INITIAL_STATE = {}

const testCreatePolicyReducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case actions.RESET_TEST_CREATE_POlICY: {
      const stateToBeReset = mapArrayElementsKeysToObjectKeys(payload)
      return { ...state, ...stateToBeReset }
    }
    case actions.GET_PACKAGES: {
      return { ...state, ...payload }
    }
    case actions.GET_PRODUCT_PACKAGE_ATTRIBUTES: {
      return { ...state, ...payload }
    }
    case actions.POST_POLICY_ATTRIBUTES: {
      return { ...state, ...payload }
    }
    case actions.POST_ENDORSEMENT: {
      return { ...state, ...payload }
    }
    default:
      return state
  }
}

export { INITIAL_STATE }
export default testCreatePolicyReducer
