import partnerUrls from '../../../../request/urls/partner'

const actions = {
  RESET_TEST_CREATE_POlICY: 'RESET_TEST_CREATE_POlICY',
  GET_PACKAGES_REQUEST: 'GET_PACKAGES_REQUEST',
  GET_PACKAGES: 'GET_PACKAGES',
  GET_PRODUCT_PACKAGE_ATTRIBUTES: 'GET_PRODUCT_PACKAGE_ATTRIBUTES',
  GET_PRODUCT_PACKAGE_ATTRIBUTES_REQUEST: 'GET_PRODUCT_PACKAGE_ATTRIBUTES_REQUEST',
  POST_POLICY_ATTRIBUTES_REQUEST: 'POST_POLICY_ATTRIBUTES_REQUEST',
  POST_POLICY_ATTRIBUTES: 'POST_POLICY_ATTRIBUTES',
  POST_ENDORSEMENT_REQUEST: 'POST_ENDORSEMENT_REQUEST',
  POST_ENDORSEMENT: 'POST_ENDORSEMENT',
  resetState: (fields = []) => ({
    type: actions.RESET_TEST_CREATE_POlICY,
    payload: fields
  }),
  getPackages: (payload) => {
    return {
      type: actions.GET_PACKAGES_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: partnerUrls.getPackages
      }
    }
  },
  getProductPackagesAttributes: (payload) => {
    return {
      type: actions.GET_PRODUCT_PACKAGE_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: partnerUrls.getProductPackgesAttributes
      }
    }
  },
  postPolicyAttributes: (payload) => {
    return {
      type: actions.POST_POLICY_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'authPost',
        url: partnerUrls.postPolicyAttributes
      }
    }
  },
  postEndorsementAttributes: (payload) => {
    return {
      type: actions.POST_ENDORSEMENT_REQUEST,
      payload: {
        ...payload,
        method: 'authPost',
        url: partnerUrls.postEndorsementAttributes
      }
    }
  }
}

export default actions
