/* eslint-disable react-hooks/exhaustive-deps */
import { useEffect, useMemo } from 'react'
import { Row, Col, Form, Button, notification } from 'antd'
import { getFormItems } from './formItem'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import { useResetState, usePolicyAttributes } from '../hooks/useTestCreatePolicy'
import { useLoaderContextValue } from '../../../../../globalContextProvider/LoaderContext'
import get from 'lodash/get'
import { FormContainer } from './policyAttributes.style'
import moment from 'moment'

function PolicyAttributes (props) {
  const { data, form, partner, product, packageKey, refPicker } = props
  const [{ postPolicyAttributesData, postPolicyAttributesStatus }, request] = usePolicyAttributes()
  const [resetTestCreatePolicyState] = useResetState()
  const [{ POST_POLICY_ATTRIBUTES_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    if (postPolicyAttributesStatus === 'success') {
      notification.success({
        message: 'Test Policy Created'
      })
      refPicker(get(postPolicyAttributesData, 'ref'))
      resetTestCreatePolicyState(['postPolicyAttributesStatus'])
    }
    if (postPolicyAttributesStatus !== 'success' && postPolicyAttributesStatus !== undefined) {
      notification.error({
        message: postPolicyAttributesStatus
      })
      resetTestCreatePolicyState(['postPolicyAttributesStatus'])
    }
  }, [postPolicyAttributesStatus])

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        if (values.year) {
          values.year = values.year.toString()
        }
        const mapValues = {
          ...values
        }
        for (const key in mapValues) {
          const keyValue = mapValues[key]
          if (moment(keyValue).isValid()) {
            if (moment(keyValue)._f === 'YYYY-MM-DDTHH:mm') {
              mapValues[key] = moment(keyValue).format('YYYY-MM-DD HH:mm:ss')
            }
          }
        }
        request({
          query: {
            product_code: product,
            partner_code: partner
          },
          body: {
            ...mapValues,
            package_id: packageKey
          }
        })
      }
    })
  }
  const formItemsRender = useMemo(() => Object.keys(data), [data])
  const refId = useMemo(() => `ref${Math.floor(100000 + Math.random() * 900000)}`, [])

  return (
    <FormContainer>
      <Form onSubmit={handleSubmit}>
        <Row type='flex' justify='center'>
          <Col span={22}>
            {
              formItemsRender.map((item, index) => {
                if (item !== 'reference_id') {
                  return getFormItems.call(this, {
                    form,
                    formName: item,
                    type: data[item],
                    label: capitalizeFirstLetter(item),
                    initialValue: data[item].prefill,
                    required: true,
                    parentKey: capitalizeFirstLetter(item)
                  })
                } else {
                  return getFormItems.call(this, {
                    form,
                    formName: item,
                    type: data[item],
                    label: capitalizeFirstLetter(item),
                    initialValue: refId,
                    required: true,
                    parentKey: capitalizeFirstLetter(item)
                  })
                }
              })
            }
          </Col>
          <Col className='submit__section' span={24}>
            <Button
              loading={POST_POLICY_ATTRIBUTES_LOADER}
              type='primary'
              htmlType='submit'
            >
              Submit
            </Button>
          </Col>
        </Row>
      </Form>
    </FormContainer>
  )
}

const WrappedPolicyAttributesForm = Form.create()(PolicyAttributes)

export default WrappedPolicyAttributesForm
