import { Row, Col, InputNumber } from 'antd'
import styled from 'styled-components'

const IntegerTypeContainer = styled.div`
padding-top:10px;
padding-bottom:10px;
border-bottom: 1px solid #d7d7d7;
.ant-input-number {
  border-radius: 15px;
}
.ant-input-number-handler-wrap{
  right: 2px;
    border-top-right-radius: 15px;
    border-bottom-right-radius: 15px;
}
`
export function YearTypeField ({ initialValue, type, formName, getFieldDecorator, label, name, prefilled }) {
  return (
    <IntegerTypeContainer>
      <Row type='flex' justify='space-between'>
        <Col span={6}>
          <span><b>{label}</b> <small>({type})</small> </span>
        </Col>
        <Col span={18}>
          {
            getFieldDecorator(formName, {
              initialValue: initialValue
            })(<InputNumber max={2150} min={1850} />)
          }
        </Col>
      </Row>
    </IntegerTypeContainer>
  )
}
