import React, { useState } from 'react'
import { Row, Col, Icon } from 'antd'
import { getFormItems } from '../formItem'
import { capitalizeFirstLetter } from '../../../../../../helpers/utility'
import { ArrayOfObjects as StyleWrapper } from './commanStyles.style'

export function ArrayOfObject ({ form, fields, formName, parentKey }) {
  const updatedFields = [{ ...fields, id: 0, showAdd: true, showDelete: false }]
  const [newFields, setFields] = useState(updatedFields)
  const parentKeyLocal = formName

  const addItem = () => {
    const lastItemId = newFields[newFields.length - 1].id
    const updatedItem = [...newFields, {
      ...updatedFields[0],
      id: lastItemId + 1
    }].map(item => {
      return {
        ...item,
        showAdd: true,
        showDelete: true
      }
    })
    setFields(updatedItem)
  }

  const remove = (id) => {
    let updatedItems = newFields.filter(item => item.id !== id)
    if (updatedItems.length === 1) {
      updatedItems = updatedItems.map(item => {
        return {
          ...item,
          showDelete: false
        }
      })
    }
    setFields(updatedItems)
  }
  return (
    <StyleWrapper>
      <div className='heading'>
        {
            parentKey &&
              <h4><b>{parentKey} (array of object)</b></h4>
        }
      </div>
      <Row type='flex' align='middle' gutter={40}>
        {
          newFields.map((fieldsItem, index) => {
            const objectItem = fieldsItem
            return (
              <React.Fragment key={index}>
                <Col span={22}>
                  {
                    Object.keys(objectItem).map((item) => {
                      const data = getFormItems.call(this, {
                        form,
                        formName: `${parentKeyLocal}[${index}].${item}`,
                        type: objectItem[item],
                        label: capitalizeFirstLetter(item),
                        initialValue: objectItem[item].prefill ? objectItem[item].prefill : '',
                        // required: true,
                        parentKey: item
                      })
                      return (
                        <Row className='padding_left' key={index} type='flex'>
                          <Col span={24}>
                            {data}
                          </Col>
                        </Row>
                      )
                    })
                  }
                </Col>
                <Col span={2}>
                  <Row type='flex' gutter={10}>
                    {
                      fieldsItem.showAdd &&
                        <Col>
                          <Icon
                            className='dynamic-add-button button-size'
                            type='plus-circle'
                            theme='filled'
                            onClick={addItem}
                          />
                        </Col>
                    }
                    {
                      fieldsItem.showDelete &&
                        <Col>
                          <Icon
                            className='dynamic-delete-button button-size'
                            type='minus-circle'
                            theme='filled'
                            onClick={() => remove(fieldsItem.id)}
                          />
                        </Col>
                    }
                  </Row>
                </Col>

              </React.Fragment>
            )
          })
        }
      </Row>
    </StyleWrapper>
  )
}
