import { useEffect } from 'react'
import { Row, Col, Form, Button, notification } from 'antd'
import { getFormItems } from './formItem'
import { capitalizeFirstLetter } from '../../../../../helpers/utility'
import styled from 'styled-components'
import { useResetState, useEndorsementAttributes } from '../hooks/useTestCreatePolicy'
import { useLoaderContextValue } from '../../../../../globalContextProvider/LoaderContext'
import moment from 'moment'

const FormContainer = styled.div`
  .submit__section {
    margin-top: 20px;
    width: 100%;
    text-align: center;
  }
`
function EndorsementAttributes (props) {
  const { data, form, refData, partner } = props
  const [{ postEndorsementStatus }, request] = useEndorsementAttributes()
  const [resetTestCreatePolicyState] = useResetState()
  const [{ POST_ENDORSEMENT_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    if (postEndorsementStatus === 'success') {
      notification.success({
        message: 'Test Endorsement Created'
      })
      resetTestCreatePolicyState(['postEndorsementStatus'])
    }
    if (postEndorsementStatus !== 'success' && postEndorsementStatus !== undefined) {
      notification.error({
        message: postEndorsementStatus
      })
      resetTestCreatePolicyState(['postEndorsementStatus'])
    }
  }, [postEndorsementStatus, resetTestCreatePolicyState])

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        if (values.year) {
          values.year = values.year.toString()
        }
        const mapValues = {
          ...values
        }
        for (const key in mapValues) {
          const keyValue = mapValues[key]
          if (moment(keyValue).isValid()) {
            if (moment(keyValue)._f === 'YYYY-MM-DDTHH:mm') {
              mapValues[key] = moment(keyValue).format('YYYY-MM-DD HH:MM:SS')
            }
          }
        }
        request({
          query: {
            ref: refData,
            partner_code: partner
          },
          body: mapValues
        })
      }
    })
  }

  return (
    <FormContainer>
      <Form onSubmit={handleSubmit}>
        <Row type='flex' justify='center'>
          <Col span={22}>
            {
              Object.keys(data).map((item, index) => {
                return getFormItems.call(this, {
                  form,
                  formName: item,
                  type: data[item],
                  label: capitalizeFirstLetter(item),
                  initialValue: '',
                  required: true,
                  parentKey: capitalizeFirstLetter(item)
                })
              })
            }
          </Col>
          <Col className='submit__section' span={24}>
            <Button
              loadin={POST_ENDORSEMENT_LOADER}
              type='primary'
              htmlType='submit'
            >
              Submit
            </Button>
          </Col>
        </Row>
      </Form>
    </FormContainer>
  )
}

const WrappedPolicyAttributesForm = Form.create()(EndorsementAttributes)

export default WrappedPolicyAttributesForm
