import { useEffect, useState, useRef } from 'react'
import { get } from 'lodash'
import { Row, Col, Button } from 'antd'
import StyleContainer from './index.style'
import CardComponent from './components/cardComponents'
import { TestCreatePolicyContextProvider } from './context'
import AccordianComponent from './components/accordian'

export default function TestCreatePolicyWrapperComponent (props) {
  const [productCode, setProductCode] = useState('')
  const [partnerCode, setPartnerCode] = useState('')
  const [packageData, setPackage] = useState('')
  const that = useRef({
    isSetProduct: false
  })

  const setPackageFunction = (item) => {
    setPackage(item)
  }
  useEffect(() => {
    if (!that.current.isSetProduct) {
      const productCode = get(props, 'match.params.product', '')
      const partnerCode = get(props, 'match.params.partner', '')
      if (productCode) {
        setProductCode(productCode)
      }
      if (partnerCode) {
        setPartnerCode(partnerCode)
      }
      that.current.isSetProduct = true
    }
  }, [props])

  const onBack = () => {
    props.history.goBack()
  }

  return (
    <StyleContainer>
      <TestCreatePolicyContextProvider>
        <Row type='flex' justify='center'>
          <Col className='button__back' span={22}>
            <Button onClick={onBack}>Back</Button>
          </Col>
          <Col span={22}>
            <CardComponent packageDataFunction={setPackageFunction} product={productCode} partner={partnerCode} />
            <AccordianComponent packageKey={packageData} product={productCode} partner={partnerCode} />
          </Col>
        </Row>
      </TestCreatePolicyContextProvider>
    </StyleContainer>
  )
}
