import { camelCase, get } from 'lodash'
import { useErrorContextValue } from '../globalContextProvider/ErrorContext'
import { useLoaderContextValue } from '../globalContextProvider/LoaderContext'
import { getErrorMessage } from '../helpers/utility'
import SERVICE_METHODS from '../request/methods'
import { ERROR_ACTIONS } from '../state/error/actions'
import { LOADER_ACTIONS } from '../state/loader/actions'

function useServiceRequest (dispatch) {
  // dispatch method pass by the caller component so that
  // it can update the value to respected store
  const [, dispatchLoader] = useLoaderContextValue()
  const [, dispatchError] = useErrorContextValue() || [{}, () => { }]
  const callApi = async ({ type, payload }) => {
    const { method } = payload
    const actionType = type.replace(/_REQUEST/g, '')
    // this update loader with respect to action type
    // like GET_DETAIL_REQUEST then loader becomes GET_DETAIL_LOADER
    // and can be access this value inside the caller component/ Parent component
    // with the help of useLoaderContextValue() returns the following status [{ GET_DETAIL_LOADER }]
    dispatchLoader({
      type: LOADER_ACTIONS.LOADER_UPDATE,
      payload: {
        [`${actionType}_LOADER`]: true
      }
    })

    const methodCall = SERVICE_METHODS[method]
    let res = {}
    try {
      res = await methodCall({ ...payload })
    } catch (error) {
      res = error
    }

    dispatch({
      type: `${actionType}`,
      payload: {
        [`${camelCase(actionType)}Data`]: res.data,
        [`${camelCase(actionType)}Status`]: ([200, 201].includes(res.status))
          ? 'success'
          : getErrorMessage(res.status, get(res, 'data.error_code'), res.data)
      }
    })

    if (res.status !== 200) {
      // update the error handler globally so that this value
      // can be accessible from any component/ child component
      dispatchError({
        type: ERROR_ACTIONS.ERROR_UPDATE,
        payload: {
          [`${actionType}_ERROR`]: true
        }
      })
    }

    dispatchLoader({
      type: LOADER_ACTIONS.LOADER_UPDATE,
      payload: {
        [`${actionType}_LOADER`]: false
      }
    })
  }

  return [callApi]
}

export default useServiceRequest
