import React from 'react'
import { InputTypeField } from './FormItemsTypes/InputType'
import { Float64TypeField } from './FormItemsTypes/float64Type'
import { IntegerTypeField } from './FormItemsTypes/integerType'
import { ObjectTypeField } from './FormItemsTypes/objectType'
import { ArrayTypeComponent } from './FormItemsTypes/ArrayType'
import { DateTimeTypeField } from './FormItemsTypes/DateTimeType'
import { BoolTypeField } from './FormItemsTypes/BoolType'
import { DateTypeField } from './FormItemsTypes/DateType'
import { YearTypeField } from './FormItemsTypes/YearType'

export function getFormItems (formData) {
  const {
    form,
    formName,
    type: Type,
    label = ' ',
    initialValue,
    parentKey
  } = formData
  const { getFieldDecorator } = form

  const { type, fields = {}, field_type: filedType } = Type
  switch (type) {
    case 'int':
      return (
        <IntegerTypeField type={filedType} initialValue={initialValue} formName={formName} label={label} getFieldDecorator={getFieldDecorator} />
      )
    case 'string':
      return (
        <InputTypeField type={filedType} initialValue={initialValue} formName={formName} label={label} getFieldDecorator={getFieldDecorator} />
      )
    case 'object':
      return (
        <ObjectTypeField
          form={form}
          parentKey={parentKey}
          fields={fields}
          formName={formName}
        />
      )
    case 'array':
      return (
        <ArrayTypeComponent
          formName={formName}
          form={form}
          fields={fields}
          type={filedType}
          parentKey={parentKey}
          getFieldDecorator={getFieldDecorator}
        />
      )
    case 'date': return (
      <DateTypeField
        initialValue={initialValue}
        label={label}
        getFieldDecorator={getFieldDecorator}
        formName={formName}
        type={filedType}
      />
    )
    case 'datetime': return (
      <DateTimeTypeField
        initialValue={initialValue}
        label={label}
        getFieldDecorator={getFieldDecorator}
        formName={formName}
        type={filedType}
      />
    )

    case 'year': return (
      <YearTypeField
        form={form}
        initialValue={initialValue}
        label={label}
        getFieldDecorator={getFieldDecorator}
        formName={formName}
        type={filedType}
      />
    )

    case 'float64':
      return (
        <Float64TypeField type={filedType} initialValue={initialValue} formName={formName} label={label} getFieldDecorator={getFieldDecorator} />
      )

    case 'bool': return (
      <BoolTypeField
        initialValue={initialValue}
        label={label}
        getFieldDecorator={getFieldDecorator}
        formName={formName}
        type={filedType}
      />
    )
    default: return null
  }
}
