import { useTestCreatePolicyContextValue } from '../context'
import useServiceRequest from '../../../../../hooks/useServiceRequest'
import actions from '../actions'

export function useResetState () {
  const [, dispatch] = useTestCreatePolicyContextValue()
  const resetTestCreatePolicyState = async (keys = []) => {
    await dispatch(actions.resetState(keys))
  }
  return [resetTestCreatePolicyState]
}

export function useGetPackageList () {
  const [{ getPackagesData, getPackagesStatus }, dispatch] = useTestCreatePolicyContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.getPackages(payload))
  }
  return [{ getPackagesData, getPackagesStatus }, request]
}

