import { ArrayOfString } from './ArrayOfStringType'
import { ArrayOfObject } from './ArrayOfObject'

export function ArrayTypeComponent ({ type, form, fields, formName, parentKey, getFieldDecorator }) {
  switch (type) {
    case 'string': return (
      <ArrayOfString
        form={form}
        formName={formName}
        parentKey={parentKey}
        getFieldDecorator={getFieldDecorator}
      />
    )
    case 'object': return (
      <ArrayOfObject
        form={form}
        fields={fields}
        formName={formName}
        parentKey={parentKey}
      />
    )
    default: return ''
  }
}
