import axios from 'axios'
import querySearchBuilder from '../../helpers/querySearchBuilder'
import { getHeader, openDocInNewTabFromUrl } from '../../helpers/utility'
import urlMapper from '../../helpers/urlMapper'

const downloadFileFromGcsRequest = ({
  signedUrl = '',
  query = {},
  body = {},
  params = {},
  signedUrlBody = {}
}) => {
  const queryString = querySearchBuilder(query)
  const mappedUrlSigned = urlMapper(signedUrl, params)
  const combinedSignedUrl = `${mappedUrlSigned}${queryString}`
  return axios
    .post(combinedSignedUrl, signedUrlBody, { headers: getHeader() })
    .then(response => {
      const { data } = response
      openDocInNewTabFromUrl(data.signed_url)
      return response
    })
    .catch(error => {
      if (error.response) {
        return error.response
      } else {
        throw error
      }
    })
}
export default downloadFileFromGcsRequest
