import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../reducer'

export const TestCreatePolicyContext = createContext()

export const TestCreatePolicyContextProvider = (props) => {
  return (
    <TestCreatePolicyContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </TestCreatePolicyContext.Provider>
  )
}

export const useTestCreatePolicyContextValue = () => useContext(TestCreatePolicyContext)
